# ==============================================================================# 034_PROCESS_MANAGER.py# ==============================================================================import sqlite3import platformimport osfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS process_manager(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    hostname TEXT,    operating_system TEXT,    python_version TEXT,    cpu_count INTEGER,    process_status TEXT)""")conn.commit()hostname = platform.node()operating_system = platform.platform()python_version = platform.python_version()cpu_count = os.cpu_count()cur.execute("""INSERT INTO process_manager(    timestamp,    hostname,    operating_system,    python_version,    cpu_count,    process_status)VALUES(?,?,?,?,?,?)""",(    datetime.now().isoformat(),    hostname,    operating_system,    python_version,    cpu_count,    "RUNNING"))conn.commit()cur.execute("""SELECT *FROM process_managerORDER BY id DESCLIMIT 1""")row = cur.fetchone()print("="*80)print("PROCESS MANAGER")print("="*80)for k in row.keys():    print(f"{k:<20}: {row[k]}")print("="*80)conn.close()

